const THEME_COLOR={"Economics":"#0D4A7A","Governance":"#3D6678","Civilian Life":"#1A5C35","Education and Militarisation":"#7A5C0D","Identity, Culture and Religion":"#6B2D8A","Coercion, Resistance and Security":"#7A1C28","Information Space":"#6B2D0D","Accountability and Legal":"#0D5C4A"};
function parseDateOrdinal(d){if(!d)return 0;const M={January:1,February:2,March:3,April:4,May:5,June:6,July:7,August:8,September:9,October:10,November:11,December:12};const m=d.match(/^(\w+)\s+(\d{4})$/);if(!m)return 0;return parseInt(m[2])*100+(M[m[1]]||0);}
